#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from __future__ import annotations

from pathlib import Path
from datetime import datetime
import shutil
import py_compile

FINALIZER_CODE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Gerador final unificado de artigo acadêmico PRISMA/ABNT.\n\nFluxo em um único executor Python:\n1. opcionalmente prepara/recupera full text;\n2. opcionalmente gera artigo longo seccional;\n3. saneia BibLaTeX;\n4. impõe biblatex-abnt autor-data;\n5. exporta ORG -> TEX;\n6. compila com pdflatex + biber;\n7. valida o PDF final.\n\nNão chama scripts Python antigos de correção. As únicas chamadas externas são\nexecutáveis necessários ao PDF: emacs, pdflatex, biber e pdftotext.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport contextlib\nimport importlib\nimport io\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Iterable\n\n\nBIBLATEX_ABNT_OPTIONS = (\n    "backend=biber,"\n    "style=abnt,"\n    "language=brazil,"\n    "sorting=nyt,"\n    "giveninits=true,"\n    "uniquename=false,"\n    "uniquelist=false"\n)\n\nBAD_PDF_PATTERNS = [\n    r"LATEX",\n    r"LaTeX",\n    r"\\[[0-9]+(?:,\\s*[0-9]+)*\\]",\n    r"Soares, Ninin e Lima \\(Soares",\n    r"Gabbay et al\\. \\(Gabbay",\n    r"Dijkstra \\(Dijkstra",\n]\n\n\ndef stamp() -> str:\n    return datetime.now().strftime("%Y%m%d_%H%M%S")\n\n\ndef project_root_from_this() -> Path:\n    here = Path(__file__).resolve()\n    for parent in [here.parent, *here.parents]:\n        if (parent / "app_bundle").exists() and (parent / "Pipfile").exists():\n            return parent\n    return Path.cwd().resolve()\n\n\ndef backup(path: Path, tag: str, quiet: bool = False) -> None:\n    if not path.exists():\n        return\n    bak = path.with_name(path.name + f".bak_{tag}_{stamp()}")\n    shutil.copy2(path, bak)\n    if not quiet:\n        print(f"[OK] Backup: {bak}")\n\n\ndef run(cmd: list[str], cwd: Path | None = None, env: dict[str, str] | None = None, quiet: bool = False) -> tuple[int, str]:\n    proc = subprocess.run(\n        cmd,\n        cwd=str(cwd) if cwd else None,\n        env=env,\n        stdout=subprocess.PIPE,\n        stderr=subprocess.STDOUT,\n        check=False,\n    )\n    out = (proc.stdout or b"").decode("utf-8", errors="replace")\n    if not quiet:\n        print("\\n$ " + " ".join(cmd))\n        print(out[-5000:])\n    return int(proc.returncode), out\n\n\ndef call_module_main(module_name: str, argv: list[str], *, quiet: bool = False) -> str:\n    """Executa main() de módulo do projeto sem subprocess."""\n    old_argv = sys.argv[:]\n    buf = io.StringIO()\n    try:\n        sys.argv = [module_name.rsplit(".", 1)[-1] + ".py", *argv]\n        cm_out = contextlib.redirect_stdout(buf) if quiet else contextlib.nullcontext()\n        cm_err = contextlib.redirect_stderr(buf) if quiet else contextlib.nullcontext()\n        with cm_out, cm_err:\n            mod = importlib.import_module(module_name)\n            if not hasattr(mod, "main"):\n                raise RuntimeError(f"Módulo sem main(): {module_name}")\n            try:\n                ret = mod.main()\n                code = 0 if ret is None else int(ret)\n            except SystemExit as exc:\n                code = 0 if exc.code is None else int(exc.code)\n        captured = buf.getvalue()\n        if code != 0:\n            raise RuntimeError(f"{module_name} terminou com código {code}.\\n{captured[-5000:]}")\n        return captured\n    finally:\n        sys.argv = old_argv\n\n\ndef set_toml_value_if_present(txt: str, key: str, value: str) -> str:\n    pat = re.compile(rf"(?m)^({re.escape(key)}\\s*=\\s*).*$")\n    return pat.sub(rf"\\1{value}", txt) if pat.search(txt) else txt\n\n\ndef ensure_cfg(cfg: Path, template_cfg: Path | None, quiet: bool = False) -> None:\n    if cfg.exists():\n        return\n    if template_cfg is None:\n        raise SystemExit(f"ERRO: TOML não encontrado: {cfg}\\nInforme --template-cfg ou crie o TOML antes.")\n    if not template_cfg.exists():\n        raise SystemExit(f"ERRO: template TOML não encontrado: {template_cfg}")\n    cfg.parent.mkdir(parents=True, exist_ok=True)\n    shutil.copy2(template_cfg, cfg)\n    if not quiet:\n        print(f"[OK] TOML criado: {cfg}")\n\n\ndef prepare_cfg(cfg: Path, target_n: int, min_palavras: int, quiet: bool = False) -> None:\n    backup(cfg, "artigo_final_unificado", quiet=quiet)\n    txt = cfg.read_text(encoding="utf-8", errors="ignore")\n    replacements = {\n        "target_n": str(target_n),\n        "target_n_fulltext": str(target_n),\n        "min_palavras": str(min_palavras),\n        "min_palavras_total": str(min_palavras),\n        "usar_biber": "true",\n        "usar_biblatex": "true",\n        "estilo_bibliografia": \'"abnt"\',\n    }\n    for key, value in replacements.items():\n        txt = set_toml_value_if_present(txt, key, value)\n    cfg.write_text(txt, encoding="utf-8")\n\n\ndef parse_bib_keys(bib: Path) -> list[str]:\n    if not bib.exists():\n        return []\n    txt = bib.read_text(encoding="utf-8", errors="ignore")\n    return re.findall(r"@\\w+\\s*\\{\\s*([^,\\s]+)", txt)\n\n\ndef sanitize_bib(bib: Path, quiet: bool = False) -> None:\n    if not bib.exists():\n        raise SystemExit(f"ERRO: BIB não encontrado: {bib}")\n    backup(bib, "bib_saneado", quiet=quiet)\n    txt = bib.read_text(encoding="utf-8", errors="ignore")\n    field_names = ["author", "editor", "title", "journaltitle", "journal", "publisher", "institution", "organization"]\n    for field in field_names:\n        pattern = re.compile(rf"(?im)^(\\s*{field}\\s*=\\s*[\\{{\\"])(.*?)([\\}}\\"],?\\s*)$")\n        def repl(m: re.Match[str]) -> str:\n            start, value, end = m.groups()\n            if field in {"author", "editor"}:\n                value = value.replace(";", " and ")\n            value = value.replace(" & ", r" \\& ")\n            return start + value + end\n        txt = pattern.sub(repl, txt)\n    bib.write_text(txt, encoding="utf-8")\n\n\ndef convert_literal_citations(txt: str, keys: list[str]) -> str:\n    if not keys:\n        return txt\n    keyset = set(keys)\n    def repl_key(m: re.Match[str]) -> str:\n        key = m.group(1)\n        return rf"\\parencite{{{key}}}" if key in keyset else m.group(0)\n    txt = re.sub(r"\\[([A-Za-z][A-Za-z0-9:_\\-.]{4,})\\]", repl_key, txt)\n    def repl_num(m: re.Match[str]) -> str:\n        raw = m.group(1)\n        nums: list[int] = []\n        for piece in raw.split(","):\n            piece = piece.strip()\n            if not piece.isdigit():\n                return m.group(0)\n            nums.append(int(piece))\n        if nums and all(1 <= n <= len(keys) for n in nums):\n            return rf"\\parencite{{{\',\'.join(keys[n - 1] for n in nums)}}}"\n        return m.group(0)\n    return re.sub(r"(?<![A-Za-z0-9])\\[([0-9]+(?:\\s*,\\s*[0-9]+)*)\\](?![A-Za-z0-9])", repl_num, txt)\n\n\ndef generic_text_fixes(txt: str) -> str:\n    novo = "evitando tabela extensa de difícil leitura e preservando a rastreabilidade das citações"\n    txt = re.sub(\n        r"evitando\\s+tabela\\s+larga\\s+no\\s*(?:LATEX|LaTeX|\\\\LaTeX(?:\\{\\})?)\\s*e\\s+preservando\\s+a\\s+rastreabilidade\\s+das\\s+citações",\n        novo,\n        txt,\n        flags=re.I,\n    )\n    for old in [\n        "evitando tabela larga no LATEX e preservando a rastreabilidade das citações",\n        "evitando tabela larga no LaTeX e preservando a rastreabilidade das citações",\n        r"evitando tabela larga no \\LaTeX{} e preservando a rastreabilidade das citações",\n        r"evitando tabela larga no \\LaTeX e preservando a rastreabilidade das citações",\n    ]:\n        txt = txt.replace(old, novo)\n    txt = txt.replace(r"$\\backslash$%", r"\\%")\n    txt = txt.replace(r"\\textbackslash{}", "")\n    return txt\n\n\ndef remove_org_bib_headers(txt: str) -> str:\n    patterns = [\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\usepackage(?:\\[[^\\]]*\\])?\\{biblatex\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\addbibresource\\{[^}]+\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\usepackage(?:\\[[^\\]]*\\])?\\{abntex2cite\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\bibliographystyle\\{[^}]+\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\bibliography\\{[^}]+\\}\\s*$",\n    ]\n    for pat in patterns:\n        txt = re.sub(pat, "", txt)\n    return txt\n\n\ndef insert_org_bib_headers(txt: str, bib_name: str) -> str:\n    lines = txt.splitlines()\n    insert_at = 0\n    for i, line in enumerate(lines):\n        if line.startswith("#+"):\n            insert_at = i + 1\n    headers = [\n        rf"#+LATEX_HEADER: \\usepackage[{BIBLATEX_ABNT_OPTIONS}]{{biblatex}}",\n        rf"#+LATEX_HEADER: \\addbibresource{{{bib_name}}}",\n    ]\n    for h in reversed(headers):\n        lines.insert(insert_at, h)\n    return "\\n".join(lines).rstrip() + "\\n"\n\n\ndef ensure_org_references(txt: str) -> str:\n    txt = re.sub(r"(?m)^\\\\bibliographystyle\\{[^}]+\\}\\s*$", "", txt)\n    txt = re.sub(r"(?m)^\\\\bibliography\\{[^}]+\\}\\s*$", "", txt)\n    if r"\\printbibliography" not in txt:\n        txt = txt.rstrip() + "\\n\\n* Referências\\n\\\\nocite{*}\\n\\\\printbibliography[heading=none]\\n"\n    return txt\n\n\ndef patch_org(org: Path, bib_name: str, keys: list[str], quiet: bool = False) -> None:\n    if not org.exists():\n        raise SystemExit(f"ERRO: ORG não encontrado: {org}")\n    backup(org, "org_abnt", quiet=quiet)\n    txt = org.read_text(encoding="utf-8", errors="ignore")\n    txt = remove_org_bib_headers(txt)\n    txt = insert_org_bib_headers(txt, bib_name)\n    txt = convert_literal_citations(txt, keys)\n    txt = txt.replace(r"\\cite{", r"\\parencite{")\n    txt = generic_text_fixes(txt)\n    txt = ensure_org_references(txt)\n    org.write_text(txt, encoding="utf-8")\n\n\ndef export_org_to_tex(org: Path, out: Path, quiet: bool = False) -> None:\n    if shutil.which("emacs") is None:\n        raise SystemExit("ERRO: emacs não encontrado no PATH.")\n    code, output = run([\n        "emacs", "--batch", "--eval",\n        f\'(progn (require (quote org)) (find-file "{org}") (org-latex-export-to-latex))\'\n    ], cwd=out, quiet=quiet)\n    if code != 0:\n        raise SystemExit(f"ERRO: exportação ORG -> TEX falhou.\\n{output[-5000:]}")\n\n\ndef remove_tex_bib_config(tex: str) -> str:\n    for pat in [\n        r"(?m)^\\\\PassOptionsToPackage\\{[^}]*\\}\\{biblatex\\}\\s*$",\n        r"(?m)^\\\\usepackage(?:\\[[^\\]]*\\])?\\{biblatex\\}\\s*$",\n        r"(?m)^\\\\addbibresource\\{[^}]+\\}\\s*$",\n        r"(?m)^\\\\usepackage(?:\\[[^\\]]*\\])?\\{abntex2cite\\}\\s*$",\n        r"(?m)^\\\\bibliographystyle\\{[^}]+\\}\\s*$",\n        r"(?m)^\\\\bibliography\\{[^}]+\\}\\s*$",\n    ]:\n        tex = re.sub(pat, "", tex)\n    return tex\n\n\ndef insert_tex_bib_config(tex: str, bib_name: str) -> str:\n    if r"\\begin{document}" not in tex:\n        raise SystemExit("ERRO: \\\\begin{document} não encontrado no TEX.")\n    insert = rf"\\usepackage[{BIBLATEX_ABNT_OPTIONS}]{{biblatex}}" + "\\n" + rf"\\addbibresource{{{bib_name}}}" + "\\n"\n    return tex.replace(r"\\begin{document}", insert + r"\\begin{document}", 1)\n\n\ndef ensure_tex_references(tex: str) -> str:\n    tex = re.sub(r"(?m)^\\\\bibliographystyle\\{[^}]+\\}\\s*$", "", tex)\n    tex = re.sub(r"(?m)^\\\\bibliography\\{[^}]+\\}\\s*$", "", tex)\n    if r"\\printbibliography" not in tex:\n        tex = tex.replace(r"\\end{document}", r"\\section{Referências}" + "\\n" + r"\\nocite{*}" + "\\n" + r"\\printbibliography[heading=none]" + "\\n" + r"\\end{document}", 1)\n    return tex\n\n\ndef patch_tex(tex_path: Path, bib_name: str, keys: list[str], quiet: bool = False) -> None:\n    if not tex_path.exists():\n        raise SystemExit(f"ERRO: TEX não encontrado: {tex_path}")\n    backup(tex_path, "tex_abnt", quiet=quiet)\n    tex = tex_path.read_text(encoding="utf-8", errors="ignore")\n    tex = remove_tex_bib_config(tex)\n    tex = insert_tex_bib_config(tex, bib_name)\n    tex = convert_literal_citations(tex, keys)\n    tex = tex.replace(r"\\cite{", r"\\parencite{")\n    tex = generic_text_fixes(tex)\n    tex = ensure_tex_references(tex)\n    tex_path.write_text(tex, encoding="utf-8")\n\n\ndef compile_pdf(out: Path, prefix: str, quiet: bool = False) -> Path:\n    for tool in ["pdflatex", "biber"]:\n        if shutil.which(tool) is None:\n            raise SystemExit(f"ERRO: {tool} não encontrado no PATH.")\n    tex = out / f"{prefix}.tex"\n    pdf = out / f"{prefix}.pdf"\n    if not tex.exists():\n        raise SystemExit(f"ERRO: TEX não encontrado: {tex}")\n    for ext in ["pdf", "aux", "bbl", "bcf", "blg", "log", "out", "run.xml", "toc"]:\n        p = out / f"{prefix}.{ext}"\n        if p.exists():\n            p.unlink()\n    env = os.environ.copy()\n    env["TEXINPUTS"] = f".:{out}:" + env.get("TEXINPUTS", "")\n    env["BIBINPUTS"] = f".:{out}:" + env.get("BIBINPUTS", "")\n    for cmd in [\n        ["pdflatex", "-file-line-error", "-interaction=nonstopmode", f"{prefix}.tex"],\n        ["biber", prefix],\n        ["pdflatex", "-file-line-error", "-interaction=nonstopmode", f"{prefix}.tex"],\n        ["pdflatex", "-file-line-error", "-interaction=nonstopmode", f"{prefix}.tex"],\n    ]:\n        code, output = run(cmd, cwd=out, env=env, quiet=quiet)\n        if code != 0:\n            raise SystemExit(f"ERRO: falha em {\' \'.join(cmd)}\\n{output[-5000:]}")\n    if not pdf.exists():\n        raise SystemExit(f"ERRO: PDF não foi gerado: {pdf}")\n    return pdf\n\n\ndef validate_pdf(pdf: Path, quiet: bool = False) -> None:\n    if shutil.which("pdftotext") is None:\n        if not quiet:\n            print("[AVISO] pdftotext ausente; validação textual pulada.")\n        return\n    code, txt = run(["pdftotext", str(pdf), "-"], quiet=True)\n    if code != 0:\n        raise SystemExit("ERRO: pdftotext falhou.")\n    hits: list[str] = []\n    for i, line in enumerate(txt.splitlines(), start=1):\n        for pat in BAD_PDF_PATTERNS:\n            if re.search(pat, line):\n                hits.append(f"{i}:{line}")\n                break\n    if hits:\n        raise SystemExit("ERRO: validação encontrou problemas no PDF final:\\n" + "\\n".join(hits[:40]))\n    if not quiet:\n        print("[OK] PDF validado.")\n\n\ndef prepare_fulltext(art: Path, cfg: Path, target_n: int, min_palavras: int, chars_por_pdf: int, quiet: bool) -> None:\n    call_module_main(\n        "app_bundle.scripts.pipeline.preparar_artigo_longo_fulltext",\n        ["--art-dir", str(art), "--cfg-art", str(cfg), "--target-n", str(target_n), "--min-palavras", str(min_palavras), "--chars-por-pdf", str(chars_por_pdf)],\n        quiet=quiet,\n    )\n\n\ndef generate_article(art: Path, cfg: Path, quiet: bool) -> None:\n    call_module_main(\n        "app_bundle.scripts.pipeline.gerar_artigo_longo_fulltext_secional",\n        ["--art-dir", str(art), "--cfg-art", str(cfg)],\n        quiet=quiet,\n    )\n\n\ndef finalize_existing(art: Path, cfg: Path, prefix: str, quiet: bool) -> Path:\n    out = art / "output"\n    org = out / f"{prefix}.org"\n    tex = out / f"{prefix}.tex"\n    bib = out / f"{prefix}.bib"\n    if not out.exists():\n        raise SystemExit(f"ERRO: output não encontrado: {out}")\n    if not org.exists():\n        raise SystemExit(f"ERRO: ORG não encontrado: {org}")\n    if not bib.exists():\n        raise SystemExit(f"ERRO: BIB não encontrado: {bib}")\n    sanitize_bib(bib, quiet=quiet)\n    keys = parse_bib_keys(bib)\n    patch_org(org, bib.name, keys, quiet=quiet)\n    export_org_to_tex(org, out, quiet=quiet)\n    patch_tex(tex, bib.name, keys, quiet=quiet)\n    pdf = compile_pdf(out, prefix, quiet=quiet)\n    validate_pdf(pdf, quiet=quiet)\n    return pdf\n\n\ndef main(argv: Iterable[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(description="Gera artigo final PRISMA/ABNT em PDF por fluxo unificado.")\n    parser.add_argument("--art-dir", required=True, help="Diretório do artigo.")\n    parser.add_argument("--cfg-art", required=True, help="TOML do artigo final.")\n    parser.add_argument("--template-cfg", default="", help="Template TOML se --cfg-art não existir.")\n    parser.add_argument("--prefix", default="", help="Prefixo dos arquivos finais. Padrão: stem do TOML.")\n    parser.add_argument("--target-n", type=int, default=20)\n    parser.add_argument("--min-palavras", type=int, default=8500)\n    parser.add_argument("--chars-por-pdf", type=int, default=18000)\n    parser.add_argument("--skip-prepare", action="store_true", help="Não prepara full text/corpus.")\n    parser.add_argument("--skip-generate", action="store_true", help="Não gera texto novo; só finaliza ORG/TEX/BIB existentes.")\n    parser.add_argument("--quiet", action="store_true")\n    args = parser.parse_args(list(argv) if argv is not None else None)\n\n    root = project_root_from_this()\n    if str(root) not in sys.path:\n        sys.path.insert(0, str(root))\n\n    art = Path(args.art_dir).expanduser().resolve()\n    cfg = Path(args.cfg_art).expanduser().resolve()\n    template = Path(args.template_cfg).expanduser().resolve() if args.template_cfg else None\n    prefix = str(args.prefix or cfg.stem).strip()\n\n    if not art.exists():\n        raise SystemExit(f"ERRO: diretório do artigo não encontrado: {art}")\n    ensure_cfg(cfg, template, quiet=args.quiet)\n    prepare_cfg(cfg, args.target_n, args.min_palavras, quiet=args.quiet)\n\n    if not args.skip_prepare:\n        prepare_fulltext(art, cfg, args.target_n, args.min_palavras, args.chars_por_pdf, args.quiet)\n    if not args.skip_generate:\n        generate_article(art, cfg, args.quiet)\n\n    pdf = finalize_existing(art, cfg, prefix, args.quiet)\n    print(f"[OK] PDF final: {pdf}")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
METHOD_BLOCK = '\n    # ------------------------------------------------------------------\n    # Fluxo PRISMA -> artigo final unificado\n    # ------------------------------------------------------------------\n\n    def cfg_research_output_dir(self, config_path: Path, cfg: dict[str, Any] | None = None) -> Path:\n        """Diretório do relatório PRISMA, distinto da saída do documento."""\n        cfg = cfg if cfg is not None else self.load_toml(config_path)\n        paths = self.section(cfg, "paths")\n        project = self.section(cfg, "projeto")\n        raw_base = paths.get("research_output_dir") or "output_pesquisa"\n        base = self.resolve_config_path(config_path, raw_base) or (config_path.parent / "output_pesquisa")\n        prefix = str(paths.get("research_prefix") or f"relatorio_prisma_{project.get(\'nome\') or config_path.stem}").strip()\n        return base / prefix if bool(paths.get("create_research_subdir", True)) else base\n\n    def _run_python_file(self, script: Path, args: list[str], *, label: str, title: str) -> int:\n        if not script.exists():\n            ui.message(title, f"Script não encontrado:\\n{script}")\n            return 1\n        command = [sys.executable, str(script), *args]\n        try:\n            proc = subprocess.run(\n                command,\n                cwd=str(ROOT),\n                stdout=subprocess.PIPE,\n                stderr=subprocess.STDOUT,\n                text=True,\n                encoding="utf-8",\n                errors="replace",\n                check=False,\n            )\n        except Exception as exc:\n            ui.message(title, f"Falha ao iniciar o comando:\\n{exc}")\n            return 1\n        output = proc.stdout or "(o comando não produziu saída textual)"\n        log_path = self._write_log(label, command, output, proc.returncode)\n        summary = f"Comando concluído com código {proc.returncode}.\\nLog operacional: {log_path}\\n\\n{\'─\' * 88}\\n{output}"\n        ui.message(title, summary, width=126)\n        return int(proc.returncode)\n\n    def _input_int(self, title: str, text: str, default: int) -> int | None:\n        raw = ui.input_text(title, text, default=str(default), width=126)\n        if raw is None:\n            return None\n        raw = str(raw).strip()\n        if not raw:\n            return default\n        try:\n            value = int(raw)\n        except ValueError:\n            ui.message(title, f"Valor inteiro inválido: {raw}")\n            return None\n        if value <= 0:\n            ui.message(title, "O valor deve ser positivo.")\n            return None\n        return value\n\n    def create_or_edit_briefing(self) -> None:\n        default_dir = str(Path(self.state.get("last_article_dir") or Path.home()).expanduser())\n        raw_dir = ui.input_text(\n            "Artigo PRISMA — briefing",\n            "Informe a pasta do artigo ou da atividade. O briefing será criado/aberto nela.",\n            default=default_dir,\n            path_completion=True,\n            only_directories=True,\n            width=126,\n        )\n        if not raw_dir:\n            return\n        art_dir = Path(raw_dir).expanduser().resolve()\n        art_dir.mkdir(parents=True, exist_ok=True)\n        self.state["last_article_dir"] = str(art_dir)\n        self._save_state()\n        briefing = art_dir / "briefing_artigo.txt"\n        if not briefing.exists():\n            briefing.write_text(\n                "Tema:\\n\\nObjetivo:\\n\\nProblema de pesquisa:\\n\\nPergunta norteadora:\\n\\nRecorte temporal:\\n\\nRecorte institucional/geográfico:\\n\\nPalavras-chave:\\n\\nBases desejadas:\\n\\nCritérios de inclusão:\\n\\nCritérios de exclusão:\\n\\nProduto final esperado:\\n\\nPadrão de formatação:\\n",\n                encoding="utf-8",\n            )\n        self.open_path(briefing)\n\n    def run_prisma_preliminary_search(self) -> None:\n        path = self.require_config()\n        if not path:\n            return\n        if not self.validate_config():\n            ui.message("Artigo PRISMA — validação", "Corrija o TOML antes de rodar a busca PRISMA preliminar.")\n            return\n        self.generate_full()\n\n    def _curadoria_prompt_default(self, config_path: Path, research_out: Path) -> str:\n        candidates: list[Path] = []\n        candidates.extend(sorted(config_path.parent.glob("prompt_curadoria*.y*ml")))\n        candidates.extend(sorted(research_out.glob("prompt_curadoria*.y*ml")) if research_out.exists() else [])\n        raw_last = str(self.state.get("last_curadoria_prompt") or "").strip()\n        if raw_last:\n            candidates.insert(0, Path(raw_last).expanduser())\n        for p in candidates:\n            if p.exists() and p.is_file():\n                return str(p.resolve())\n        return ""\n\n    def run_prisma_ai_cut(self) -> None:\n        path = self.require_config()\n        if not path:\n            return\n        try:\n            cfg = self.load_toml(path)\n            research_out = self.cfg_research_output_dir(path, cfg)\n        except Exception as exc:\n            ui.message("Artigo PRISMA — curadoria IA", f"Não foi possível calcular a saída PRISMA:\\n{exc}")\n            return\n        prompt_default = self._curadoria_prompt_default(path, research_out)\n        prompt = ui.input_text(\n            "Artigo PRISMA — XLSX cut pela IA",\n            "Prompt YAML de curadoria. Deixe em branco para usar o default interno do script.",\n            default=prompt_default,\n            path_completion=True,\n            allowed_suffixes=(".yaml", ".yml"),\n            width=126,\n        )\n        if prompt is None:\n            return\n        max_incluir = self._input_int("Artigo PRISMA — curadoria", "Número máximo de referências a incluir no XLSX cut:", int(self.state.get("last_target_n") or 20))\n        if max_incluir is None:\n            return\n        top_n = self._input_int("Artigo PRISMA — curadoria", "Número de candidatos para a curadoria IA:", int(self.state.get("last_top_n_candidatos") or 90))\n        if top_n is None:\n            return\n        limiar = self._input_int("Artigo PRISMA — curadoria", "Limiar mínimo de inclusão sugerida:", int(self.state.get("last_limiar_minimo") or 45))\n        if limiar is None:\n            return\n        self.state["last_target_n"] = int(max_incluir)\n        self.state["last_top_n_candidatos"] = int(top_n)\n        self.state["last_limiar_minimo"] = int(limiar)\n        if str(prompt).strip():\n            self.state["last_curadoria_prompt"] = str(Path(prompt).expanduser().resolve())\n        self._save_state()\n        args = [\n            "--config", str(path),\n            "--prisma-curadoria-ia",\n            "--prisma-curadoria-out-dir", str(research_out),\n            "--prisma-curadoria-max-incluir", str(max_incluir),\n            "--prisma-curadoria-top-n-candidatos", str(top_n),\n            "--prisma-curadoria-limiar-minimo", str(limiar),\n        ]\n        if str(prompt).strip():\n            args.extend(["--prisma-curadoria-prompt", str(Path(prompt).expanduser().resolve())])\n        self.run_command(args, label="prisma_curadoria_ia", title="Artigo PRISMA — XLSX cut pela IA")\n\n    def open_prisma_review_xlsx(self) -> None:\n        path = self.require_config()\n        if not path:\n            return\n        cfg = self.load_toml(path)\n        research_out = self.cfg_research_output_dir(path, cfg)\n        candidates: list[Path] = []\n        if research_out.exists():\n            for pattern in ["*.curadoria_ia_referencias.xlsx", "*.triagem_titulo_resumo.xlsx", "*.matriz_estudos_incluidos.xlsx"]:\n                candidates.extend(research_out.glob(pattern))\n        candidates = sorted(set(candidates), key=lambda p: p.stat().st_mtime, reverse=True)\n        if not candidates:\n            ui.message("Artigo PRISMA — revisão XLSX", f"Nenhum XLSX de curadoria/triagem encontrado em:\\n{research_out}")\n            return\n        selected = ui.select_one(\n            "Artigo PRISMA — revisão humana do XLSX",\n            "Abra a planilha, revise as decisões de inclusão/exclusão e salve antes de continuar.",\n            [(str(p), f"{p.name}\\n{p}") for p in candidates],\n            default=str(candidates[0]),\n            width=126,\n        )\n        if selected:\n            self.open_path(Path(str(selected)))\n\n    def generate_prisma_final_from_review(self) -> None:\n        path = self.require_config()\n        if not path:\n            return\n        cfg = self.load_toml(path)\n        research_out = self.cfg_research_output_dir(path, cfg)\n        candidates = sorted(research_out.glob("*.curadoria_ia_referencias.xlsx"), key=lambda p: p.stat().st_mtime, reverse=True) if research_out.exists() else []\n        default = str(candidates[0]) if candidates else ""\n        raw = ui.input_text(\n            "Artigo PRISMA — gerar PRISMA final",\n            "Selecione o XLSX revisado. O sistema reexportará para triagem_humana.csv e importará no PRISMA final.",\n            default=default,\n            path_completion=True,\n            allowed_suffixes=(".xlsx", ".csv"),\n            width=126,\n        )\n        if not raw:\n            return\n        reviewed = Path(raw).expanduser().resolve()\n        rc = self.run_command(\n            ["--config", str(path), "--prisma-curadoria-reexportar-xlsx", "--prisma-curadoria-input", str(reviewed), "--prisma-curadoria-out-dir", str(research_out)],\n            label="prisma_reexportar_xlsx",\n            title="Artigo PRISMA — reexportar XLSX revisado",\n        )\n        if rc != 0:\n            return\n        self.run_command(\n            ["--config", str(path), "--prisma-curadoria-importar", "--prisma-curadoria-out-dir", str(research_out)],\n            label="prisma_final_importar",\n            title="Artigo PRISMA — PRISMA final",\n        )\n\n    def _ask_article_final_settings(self) -> tuple[Path, Path, int, int, int] | None:\n        default_dir = str(self.state.get("last_article_dir") or Path.home())\n        raw_dir = ui.input_text(\n            "Artigo final — pasta do artigo",\n            "Informe a pasta do artigo final. Ela deve conter o TOML do artigo e receberá output/. Também será usada para full text/corpus.",\n            default=default_dir,\n            path_completion=True,\n            only_directories=True,\n            width=126,\n        )\n        if not raw_dir:\n            return None\n        art_dir = Path(raw_dir).expanduser().resolve()\n        if not art_dir.exists():\n            if not ui.confirm("Artigo final — criar pasta", f"A pasta não existe. Criar?\\n{art_dir}", default=True):\n                return None\n            art_dir.mkdir(parents=True, exist_ok=True)\n        tomls = sorted(art_dir.glob("*.toml"), key=lambda p: p.stat().st_mtime, reverse=True)\n        default_cfg = str(self.state.get("last_article_cfg") or (tomls[0] if tomls else art_dir / "artigo_final.toml"))\n        raw_cfg = ui.input_text(\n            "Artigo final — TOML do artigo",\n            "Informe o TOML do artigo final. Ele pode ter sido gerado/congelado a partir do PRISMA final.",\n            default=default_cfg,\n            path_completion=True,\n            allowed_suffixes=(".toml",),\n            width=126,\n        )\n        if not raw_cfg:\n            return None\n        cfg_art = Path(raw_cfg).expanduser().resolve()\n        target_n = self._input_int("Artigo final — parâmetros", "Quantidade alvo de estudos full text:", int(self.state.get("last_target_n") or 20))\n        if target_n is None:\n            return None\n        min_palavras = self._input_int("Artigo final — parâmetros", "Mínimo de palavras do artigo:", int(self.state.get("last_min_palavras") or 8500))\n        if min_palavras is None:\n            return None\n        chars_pdf = self._input_int("Artigo final — parâmetros", "Caracteres por PDF full text na preparação do corpus:", int(self.state.get("last_chars_por_pdf") or 18000))\n        if chars_pdf is None:\n            return None\n        self.state["last_article_dir"] = str(art_dir)\n        self.state["last_article_cfg"] = str(cfg_art)\n        self.state["last_target_n"] = int(target_n)\n        self.state["last_min_palavras"] = int(min_palavras)\n        self.state["last_chars_por_pdf"] = int(chars_pdf)\n        self._save_state()\n        return art_dir, cfg_art, target_n, min_palavras, chars_pdf\n\n    def generate_article_final_unified(self) -> None:\n        settings = self._ask_article_final_settings()\n        if settings is None:\n            return\n        art_dir, cfg_art, target_n, min_palavras, chars_pdf = settings\n        if not cfg_art.exists():\n            ui.message("Artigo final — TOML ausente", f"O TOML informado não existe:\\n{cfg_art}\\n\\nGere o TOML do artigo a partir do PRISMA final antes de continuar.")\n            return\n        if not ui.confirm("Artigo final — gerar PDF", "Executar o gerador unificado agora? Esta etapa pode demorar.", default=True):\n            return\n        rc = self._run_python_file(\n            ARTICLE_FINALIZER,\n            ["--art-dir", str(art_dir), "--cfg-art", str(cfg_art), "--target-n", str(target_n), "--min-palavras", str(min_palavras), "--chars-por-pdf", str(chars_pdf), "--quiet"],\n            label="artigo_final_unificado",\n            title="Artigo final — gerador unificado",\n        )\n        if rc == 0:\n            pdf = art_dir / "output" / f"{cfg_art.stem}.pdf"\n            msg = f"PDF final gerado com sucesso.\\n\\nEsperado em:\\n{pdf}"\n            ui.message("Artigo final — concluído", msg, width=126)\n            if pdf.exists() and ui.confirm("Artigo final — abrir PDF", "Abrir o PDF final agora?", default=True):\n                self.open_path(pdf)\n\n    def open_article_output_folder(self) -> None:\n        raw = str(self.state.get("last_article_dir") or "").strip()\n        if not raw:\n            settings = self._ask_article_final_settings()\n            if settings is None:\n                return\n            art_dir = settings[0]\n        else:\n            art_dir = Path(raw).expanduser().resolve()\n        out = art_dir / "output"\n        if not out.exists():\n            ui.message("Artigo final — saída", f"Pasta output ainda não existe:\\n{out}")\n            return\n        self.open_path(out)\n\n    def menu_prisma_article_flow(self) -> None:\n        while True:\n            path = self.active_config()\n            active = f"TOML PRISMA ativo: {path}" if path else "TOML PRISMA ativo: nenhum"\n            last_art = self.state.get("last_article_dir") or "não definido"\n            description = (\n                "Fluxo metodológico para artigo PRISMA até PDF final.\\n\\n"\n                "1) briefing; 2) TOML PRISMA; 3) PRISMA preliminar; 4) XLSX cut IA; "\n                "5) revisão humana; 6) PRISMA final; 7) gerador unificado.\\n\\n"\n                f"{active}\\nPasta de artigo final: {last_art}"\n            )\n            choice = ui.menu(\n                "Academic Pipeline — Artigo PRISMA até PDF final",\n                description,\n                [\n                    ("briefing", "[1] Criar/abrir briefing do artigo", ["1", "b"]),\n                    ("toml", "[2] Gerar TOML PRISMA preliminar pelo assistente", ["2"]),\n                    ("select", "[3] Selecionar TOML PRISMA existente", ["3", "s"]),\n                    ("prelim", "[4] Rodar pesquisa PRISMA preliminar", ["4", "p"]),\n                    ("cut", "[5] Gerar XLSX cut de referências pela IA", ["5", "x"]),\n                    ("openxlsx", "[6] Abrir XLSX para revisão humana", ["6", "r"]),\n                    ("finalprisma", "[7] Gerar PRISMA final a partir do XLSX revisado", ["7", "f"]),\n                    ("article", "[8] Rodar gerador unificado e abrir PDF final", ["8", "g"]),\n                    ("out", "[9] Abrir pasta output do artigo final", ["9", "o"]),\n                    ("back", "[0] Voltar ao painel", ["0", "v", "q"]),\n                ],\n                width=126,\n            )\n            if choice in {None, "back"}:\n                return\n            if choice == "briefing":\n                self.create_or_edit_briefing()\n            elif choice == "toml":\n                self.run_wizard("relatorio_prisma_busca_orientada_fgv")\n            elif choice == "select":\n                self.choose_existing_config()\n            elif choice == "prelim":\n                self.run_prisma_preliminary_search()\n            elif choice == "cut":\n                self.run_prisma_ai_cut()\n            elif choice == "openxlsx":\n                self.open_prisma_review_xlsx()\n            elif choice == "finalprisma":\n                self.generate_prisma_final_from_review()\n            elif choice == "article":\n                self.generate_article_final_unified()\n            elif choice == "out":\n                self.open_article_output_folder()\n'


def stamp() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def backup(path: Path, tag: str) -> Path:
    bak = path.with_name(path.name + f".bak_{tag}_{stamp()}")
    shutil.copy2(path, bak)
    print(f"[OK] Backup: {bak}")
    return bak


def find_root() -> Path:
    cwd = Path.cwd().resolve()
    for base in [cwd, *cwd.parents]:
        if (base / "app_bundle" / "scripts" / "pipeline" / "academic_pipeline_tui.py").exists():
            return base
    raise SystemExit("ERRO: rode este aplicador na raiz do projeto academic_pipeline_rc10_7_conformidade.")


def ensure_finalizer(root: Path) -> None:
    paths = [
        root / "app_bundle" / "scripts" / "pipeline" / "gerar_artigo_final_unificado.py",
        root / "gerar_artigo_final_unificado.py",
    ]
    for p in paths:
        if p.exists():
            backup(p, "tui_artigo_prisma_v1")
        p.write_text(FINALIZER_CODE, encoding="utf-8")
        p.chmod(0o755)
        py_compile.compile(str(p), doraise=True)
        print(f"[OK] Gerador unificado instalado: {p}")


def patch_tui(root: Path) -> None:
    tui = root / "app_bundle" / "scripts" / "pipeline" / "academic_pipeline_tui.py"
    backup(tui, "tui_artigo_prisma_v1")
    txt = tui.read_text(encoding="utf-8", errors="ignore")

    if "ARTICLE_FINALIZER" not in txt:
        marker = 'TOML_WIZARD = HERE.with_name("academic_pipeline_toml_generator_interativo.py")\n'
        repl = marker + 'ARTICLE_FINALIZER = HERE.with_name("gerar_artigo_final_unificado.py")\n'
        if marker not in txt:
            raise SystemExit("ERRO: não localizei TOML_WIZARD para inserir ARTICLE_FINALIZER.")
        txt = txt.replace(marker, repl, 1)

    if "def cfg_research_output_dir" not in txt:
        marker = "    # ------------------------------------------------------------------\n    # Saídas e integração com desktop\n    # ------------------------------------------------------------------\n"
        if marker not in txt:
            raise SystemExit("ERRO: não localizei bloco de Saídas para inserir métodos do fluxo PRISMA/artigo.")
        txt = txt.replace(marker, METHOD_BLOCK + "\n" + marker, 1)

    if '("article_prisma", "[7] Artigo PRISMA — fluxo completo até PDF final", ["7", "a"]),' not in txt:
        old = '                    ("outputs", "[6] Abrir PDF, DOCX, ORG, relatórios e logs", ["6", "o"]),\n                    ("exit", "[0] Sair", ["0", "q"]),'
        new = '                    ("outputs", "[6] Abrir PDF, DOCX, ORG, relatórios e logs", ["6", "o"]),\n                    ("article_prisma", "[7] Artigo PRISMA — fluxo completo até PDF final", ["7", "a"]),\n                    ("exit", "[0] Sair", ["0", "q"]),'
        if old not in txt:
            raise SystemExit("ERRO: não localizei a lista do menu principal para inserir opção 7.")
        txt = txt.replace(old, new, 1)

    if 'elif choice == "article_prisma":\n                self.menu_prisma_article_flow()' not in txt:
        old = '            elif choice == "outputs":\n                self.menu_outputs()\n'
        new = '            elif choice == "outputs":\n                self.menu_outputs()\n            elif choice == "article_prisma":\n                self.menu_prisma_article_flow()\n'
        if old not in txt:
            raise SystemExit("ERRO: não localizei o dispatch de outputs para inserir article_prisma.")
        txt = txt.replace(old, new, 1)

    tui.write_text(txt, encoding="utf-8")
    py_compile.compile(str(tui), doraise=True)
    print(f"[OK] TUI atualizada: {tui}")


def main() -> int:
    root = find_root()
    ensure_finalizer(root)
    patch_tui(root)
    print("\n[OK] Fluxo TUI PRISMA→artigo final instalado.")
    print("Execute:")
    print("  pipenv run python app_bundle/scripts/pipeline/academic_pipeline_tui.py")
    print("\nNo menu principal, use a opção 7: Artigo PRISMA — fluxo completo até PDF final.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
